// ---------- slate labels: the top of each layer, and the fossil you are looking at ----------
function slate(lines, w = 760) { const c = document.createElement("canvas"); c.width = w; c.height = 40 + lines.length * 44; const g = c.getContext("2d"); g.fillStyle = "rgba(10,24,36,.85)"; g.beginPath(); g.roundRect(0, 0, w, c.height, 18); g.fill();
  lines.forEach(([t, col, big], i) => { g.fillStyle = col; g.font = `${big ? 700 : 500} ${big ? 38 : 28}px -apple-system, Helvetica, sans-serif`; let s = t; while (g.measureText(s).width > w - 40 && s.length > 4) s = s.slice(0, -2); if (s !== t) s += "…"; g.fillText(s, 20, 50 + i * 44); });
  const t = new THREE.CanvasTexture(c); t.colorSpace = THREE.SRGBColorSpace; return { t, a: c.height / w }; }
const LAYER_LBL = [], LBL_A = Math.PI / 2;
STRATA.forEach(([name, top, bot, age, , , col], i) => { if (bot <= TOP_FT + 1) return; const ft = Math.max(top, TOP_FT), y = yOfFt(ft) - 0.3, { t, a } = slate([[name, "#ffe9a8", true], [`${Math.round(ft + GRADE / -FT2M)} ft below your floor  ·  ${Math.round(ft * FT2M)} m below ground`, "#e6f3f9"], [age, "#a9c6d4"]]);
  const mat = under(new THREE.SpriteMaterial({ map: t, transparent: true, toneMapped: false })), sp = new THREE.Sprite(mat); sp.scale.set(0.62, 0.62 * a, 1); sp.position.set(Math.cos(LBL_A) * (R_HOLE - 0.32), y, Math.sin(LBL_A) * (R_HOLE - 0.32)); sp.renderOrder = 2; HOLE.add(sp);
  const band = addU(new THREE.Mesh(new THREE.CylinderGeometry(R_HOLE - 0.004, R_HOLE - 0.004, 0.02, 48, 1, true, LBL_A - 0.5, 1.0), new THREE.MeshBasicMaterial({ color: col, side: THREE.BackSide, toneMapped: false }))); band.position.y = yOfFt(ft);
  LAYER_LBL.push({ sp, band, y, i }); });
